import sys

def main():
    lines = [line.strip() for line in sys.stdin]
    i = 0
    while i < len(lines):
        name = lines[i]
        i += 1
        if i >= len(lines):
            break
        status = lines[i]
        i += 1
        if i >= len(lines):
            break
        title = lines[i]
        i += 1

        if title.lower() == 'quit':
            print("Quitting the program.")
            break

        if status == 'faculty':
            print("Faculty members can only borrow DVDs.")
            print("Quitting the program.")
            break
        else:
            print(f'Book "{title}" successfully borrowed by {name}.')
            if i < len(lines) and lines[i].lower() == 'quit':
                print("Quitting the program.")
                break

if __name__ == "__main__":
    main()
